import{_ as t,o as r,c as d,a2 as a}from"./chunks/framework.CdvW4CUT.js";const p=JSON.parse('{"title":"结构只读沙盒与界面预览 (Preview)","description":"","frontmatter":{},"headers":[],"relativePath":"1.21.4/rendering/structure-preview.md","filePath":"1.21.4/rendering/structure-preview.md"}'),o={name:"1.21.4/rendering/structure-preview.md"};function i(c,e,s,n,l,u){return r(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="结构只读沙盒与界面预览-preview" tabindex="-1">结构只读沙盒与界面预览 (<code>Preview</code>) <a class="header-anchor" href="#结构只读沙盒与界面预览-preview" aria-label="Permalink to &quot;结构只读沙盒与界面预览 (`Preview`)&quot;">​</a></h1><p><code>dev.anvilcraft.lib.v2.rendering.preview</code> 提供了一套完整的隔离沙盒世界与客户端 GUI 悬停 3D 结构预览系统。它支持从 <code>StructureTemplate</code> 构建零副作用只读微世界，并能在配方界面、物品提示或方块详单屏幕中渲染可交互拖拽旋转、支持鼠标拾取检查方块实体内容的 3D 结构预览窗口。</p><h2 id="只读沙盒世界-structuresandboxfactory-sandboxrenderlevel" tabindex="-1">只读沙盒世界：<code>StructureSandboxFactory</code> &amp; <code>SandboxRenderLevel</code> <a class="header-anchor" href="#只读沙盒世界-structuresandboxfactory-sandboxrenderlevel" aria-label="Permalink to &quot;只读沙盒世界：`StructureSandboxFactory` &amp; `SandboxRenderLevel`&quot;">​</a></h2><h3 id="structuresandboxfactory" tabindex="-1"><code>StructureSandboxFactory</code> <a class="header-anchor" href="#structuresandboxfactory" aria-label="Permalink to &quot;`StructureSandboxFactory`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法签名</th><th>说明</th></tr></thead><tbody><tr><td><code>create(@Nullable Level clientLevel, StructureTemplate template, BlockPos placementPos)</code></td><td>将 <code>StructureTemplate</code> 放入隔离的 <code>SandboxRenderLevel</code> 并初始化区块缓存；若 <code>clientLevel == null</code> 或模板尺寸为空返回 <code>null</code></td></tr><tr><td><code>centeredPlacement(StructureTemplate template)</code></td><td>计算将结构中心锚定在坐标原点附近的推荐偏移 <code>BlockPos</code></td></tr></tbody></table><h3 id="沙盒组成-sandboxrenderlevel-delegatingserverlevelaccessor-sandboxlevelchunk" tabindex="-1">沙盒组成：<code>SandboxRenderLevel</code> / <code>DelegatingServerLevelAccessor</code> / <code>SandboxLevelChunk</code> <a class="header-anchor" href="#沙盒组成-sandboxrenderlevel-delegatingserverlevelaccessor-sandboxlevelchunk" aria-label="Permalink to &quot;沙盒组成：`SandboxRenderLevel` / `DelegatingServerLevelAccessor` / `SandboxLevelChunk`&quot;">​</a></h3><ul><li><code>SandboxRenderLevel</code> 继承 <code>ClientLevel</code> 并在其中运行虚拟区块供应器 <code>SandboxChunkProvider</code>、<code>SandboxLevelChunk</code> 与光照管理 <code>PreviewLightmapAtlas</code>，支持动态时间流逝（<code>tickFrameClock()</code>）驱动液体动画纹理与发光渲染。</li><li><code>DelegatingServerLevelAccessor</code> 实现 <code>ServerLevelAccessor</code>，在需要触发服务端风格查询时（兼容多模组结构填充与特性逻辑）提供只读代理，不修改真实世界状态。</li></ul><h2 id="_3d-渲染与相机控制-structurepreviewrenderer-viewportcamerarig" tabindex="-1">3D 渲染与相机控制：<code>StructurePreviewRenderer</code> &amp; <code>ViewportCameraRig</code> <a class="header-anchor" href="#_3d-渲染与相机控制-structurepreviewrenderer-viewportcamerarig" aria-label="Permalink to &quot;3D 渲染与相机控制：`StructurePreviewRenderer` &amp; `ViewportCameraRig`&quot;">​</a></h2><h3 id="viewportcamerarig-正交-等轴测相机" tabindex="-1"><code>ViewportCameraRig</code> 正交/等轴测相机 <a class="header-anchor" href="#viewportcamerarig-正交-等轴测相机" aria-label="Permalink to &quot;`ViewportCameraRig` 正交/等轴测相机&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法 / 枚举</th><th>说明</th></tr></thead><tbody><tr><td><code>new ViewportCameraRig()</code></td><td>初始化默认正交预览相机控制架</td></tr><tr><td><code>configureViewport(int width, int height)</code></td><td>设置当前离屏或裁剪窗口像素宽高比</td></tr><tr><td><code>applyPreset(PerspectivePreset preset)</code></td><td>快速切换预设视角（包含正交等轴测与多方位预设，实现 <code>StringRepresentable</code>）</td></tr><tr><td><code>setOrthographicAngles(float yawDeg, float pitchDeg, float rollDeg)</code></td><td>自定义俯仰角、偏航角与滚转角</td></tr><tr><td><code>buildViewMatrix()</code> / <code>buildProjectionMatrix()</code></td><td>构造供 Blaze3D <code>ModelViewStack</code> 和 <code>RenderSystem.setProjectionMatrix(..., ProjectionType.ORTHOGRAPHIC)</code> 使用的矩阵</td></tr></tbody></table><h3 id="structurepreviewrenderer" tabindex="-1"><code>StructurePreviewRenderer</code> <a class="header-anchor" href="#structurepreviewrenderer" aria-label="Permalink to &quot;`StructurePreviewRenderer`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>说明</th></tr></thead><tbody><tr><td><code>StructurePreviewRenderer.getInstance()</code></td><td>获取全局渲染器单例</td></tr><tr><td><code>render(SandboxRenderLevel, ViewportCameraRig, MultiBufferSource.BufferSource[, int minY, int maxYExclusive][, Effects effects])</code></td><td>按相机架配置清深度缓冲（<code>RenderSystem.clear(GlConst.GL_DEPTH_BUFFER_BIT)</code>）、禁用雾效（<code>FogParameters.NO_FOG</code>），先渲染不透明方块与 <code>Entity</code> / <code>BlockEntity</code>，再渲染半透明图层并提交批处理</td></tr><tr><td><code>renderContent(SandboxRenderLevel, MultiBufferSource.BufferSource[, minY, maxYExclusive, Effects])</code></td><td>在外层自行管理矩阵和相机时直接提交场景几何内容</td></tr><tr><td><code>markFluidSpritesActive(FluidState fluidState)</code></td><td>配合 <code>SodiumSpriteBridge.pingSpriteUsage(...)</code> 在使用 Sodium 优化模组时通知纹理动画保持每帧更新，避免沙盒水面/岩浆卡帧静止</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>在 1.21.4 中，实体渲染已经全面采用 <code>EntityRenderState</code> 管线。<code>StructurePreviewRenderer</code> 会自动对每个实体调用 <code>renderer.createRenderState(entity, partialTicks)</code> 并传给 <code>renderer.render(renderState, poseStack, buffers, packedLight)</code>，调用方无需手动维护实体状态缓存。</p></div><h2 id="gui-悬停预览浮窗-structureguipreview-structureguiproviders" tabindex="-1">GUI 悬停预览浮窗：<code>StructureGuiPreview</code> &amp; <code>StructureGuiProviders</code> <a class="header-anchor" href="#gui-悬停预览浮窗-structureguipreview-structureguiproviders" aria-label="Permalink to &quot;GUI 悬停预览浮窗：`StructureGuiPreview` &amp; `StructureGuiProviders`&quot;">​</a></h2><p>如果需要在 JEI/EMI 配方或物品说明（如带有结构的工具）旁渲染一个随鼠标锚点缩放淡入的 3D 结构预览卡，可以使用 <code>StructureGuiPreview</code> 与 <code>StructureGuiSession</code>：</p><h3 id="注册结构来源-structureguiproviders" tabindex="-1">注册结构来源：<code>StructureGuiProviders</code> <a class="header-anchor" href="#注册结构来源-structureguiproviders" aria-label="Permalink to &quot;注册结构来源：`StructureGuiProviders`&quot;">​</a></h3><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">StructureGuiProviders.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">register</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ResourceLocation.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fromNamespaceAndPath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mymod&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;multiblock_core&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    (StructureGuiProviders.Context ctx) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        // ctx 提供 level()、player()、pos() 与 template()</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        // 可在此对特定方块位置附加提示、检查激活条件或追加元数据</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> List.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">of</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><h3 id="structureguipreview-生命周期与交互-api" tabindex="-1"><code>StructureGuiPreview</code> 生命周期与交互 API <a class="header-anchor" href="#structureguipreview-生命周期与交互-api" aria-label="Permalink to &quot;`StructureGuiPreview` 生命周期与交互 API&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>说明</th></tr></thead><tbody><tr><td><code>new StructureGuiPreview()</code> / <code>new StructureGuiPreview(BooleanSupplier reducedMotion)</code></td><td>创建 GUI 预览浮窗；可接入客户端无障碍减弱动画配置</td></tr><tr><td><code>open(Object owner, StructureTemplate template, BlockPos pos, float anchorX, float anchorY)</code></td><td>打开面向指定 <code>owner</code> 的结构预览；若结构有效则返回 <code>true</code> 并平滑过渡展开</td></tr><tr><td><code>beginFrame()</code></td><td>每帧渲染开始前重置锚定标记</td></tr><tr><td><code>anchor(float x, float y, boolean visible)</code></td><td>绑定屏幕上的目标触发锚点位置与本帧可见性</td></tr><tr><td><code>contains(double mouseX, double mouseY)</code></td><td>检查鼠标是否在预览面板区域内（用于接管滚轮/悬停交互）</td></tr><tr><td><code>mouseClicked(...)</code> / <code>mouseDragged(...)</code> / <code>mouseReleased(...)</code></td><td>将鼠标左键/右键拖拽与点击转交内部 <code>ViewportCameraRig</code> 旋转视角及射线拾取方块</td></tr><tr><td><code>blockFor(Object component)</code></td><td>反查当前渲染或关联组件对应的沙盒局部 <code>BlockPos</code></td></tr><tr><td><code>render(GuiGraphics graphics)</code></td><td>在 <code>Screen#render</code> 中绘制预览面板，内部利用 <code>StructureGuiSession.renderOnly(progress, ...)</code> 配合 <code>RenderSystem.setShaderColor</code> 统一控制面板整体透明度淡入淡出</td></tr><tr><td><code>clear()</code></td><td>关闭预览并清理关联沙盒资源</td></tr></tbody></table><h2 id="射线拾取与详情分页-structurepreviewpicker-structuredetailspager" tabindex="-1">射线拾取与详情分页：<code>StructurePreviewPicker</code> &amp; <code>StructureDetailsPager</code> <a class="header-anchor" href="#射线拾取与详情分页-structurepreviewpicker-structuredetailspager" aria-label="Permalink to &quot;射线拾取与详情分页：`StructurePreviewPicker` &amp; `StructureDetailsPager`&quot;">​</a></h2><ul><li><code>StructurePreviewPicker.pick(SandboxRenderLevel level, Vec3 start, Vec3 end, int minY, int maxY)</code>：对沙盒内限定 Y 层区间执行射线追踪并返回首个命中的 <code>BlockPos</code>（支持镂空裁剪层拾取）；</li><li><code>StructurePreviewPicker.tooltip(SandboxRenderLevel level, BlockPos pos, BlockPos placementPos)</code>：自动抽取目标位置的方块名称、属性状态以及通过 <code>StructureBlockEntityDetails</code> 解析出的方框内部库存/流体摘要文本；</li><li><code>StructureDetailsPager</code>：多行提示分页与滚轮翻页控制器（<code>visible(Font, screenWidth, screenHeight)</code>、<code>scroll(double amount)</code>），解决复杂机器提示超出屏幕高度的问题。</li></ul>',21)])])}const k=t(o,[["render",i]]);export{p as __pageData,k as default};
